'use strict';
window.HerbVectorUI=(()=>{
 const d=window.HERB_DATA,c=window.FORMULA_CORPUS,Q=window.QuantModel;
 const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const num=x=>Number.isFinite(x)?new Intl.NumberFormat('zh-TW',{maximumFractionDigits:3}).format(x):'未知';
 const pct=x=>Number.isFinite(x)?num(x*100)+'%':'未知';
 const range=x=>x?x.map(num).join(' ～ '):'未知';
 const H=id=>d.herbs.find(h=>h.id===id),F=id=>c.formulas.find(f=>f.id===id);
 const link=(url,title)=>/^https:\/\//.test(url||'')?'<a class="small-link" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(title)+' ↗</a>':esc(title);
 const source=id=>{const s=[...d.sources,...c.sources].find(x=>x.id===id);return s?link(s.url,s.title):'來源未錄'};
 let ctx,model=null,search='',supportFilter='',page=0,herbId='gancao',formulaId=c.formulas.find(f=>f.name==='桂枝湯')?.id||c.formulas[0]?.id,prediction=null,runArtifact=null;
 const report=()=>window.HERB_VECTOR_DATA;
 const V=()=>window.HerbVectorModel;
 function workbenchSignature(){return JSON.stringify({rows:ctx.selection(),origin:ctx.origin?.()?.id,name:ctx.name(),massContext:ctx.massContext?.(),basis:ctx.processing().basis})}
 function getModel(){if(!model)model=V().fit(d,c);return model}
 function vectors(){return report()?.herbVectors||d.herbs.map(h=>V().sourceVector(h))}
 function matches(){return vectors().filter(h=>(!search||[h.name,h.id,h.thermal?.recorded,...h.effects?.recorded||[]].join(' ').includes(search))&&(!supportFilter||(supportFilter==='learned'?h.learned?.mappedElements?.some(e=>e.reportable):!h.learned?.mappedElements?.some(e=>e.reportable))))}
 function learnedState(h){const a=h.learned?.mappedElements||[];return a.some(e=>e.reportable)?'可估條件關聯':a.length?'支持不足／不可單味辨識':'尚無原方對映'}
 function downloads(){return '<div class="research-downloads"><a class="button secondary" href="downloads/herb-vectors.csv" download>下載逐味向量 CSV</a><a class="button secondary" href="downloads/herb-vector-report.json" download>下載模型與留出結果</a><a class="button secondary" href="downloads/herb-vector-methodology.json" download>查看完整模型方法</a><a class="button secondary" href="downloads/tcm-research-library.zip" download>下載可重建研究資料包</a></div>'}
 function metricsHTML(r){if(!r?.performed)return '<p class="rule-note">尚未取得留出驗證結果。</p>';const m=r.metrics||{},b=r.baselineMetrics||{};return '<div class="notice '+(m.brier>b.brier||m.microF1===0?'model-caution':'')+'"><strong>真正留出方族後的文獻內驗證</strong><br>模型 Brier '+num(m.brier)+' ／訓練詞頻基準 '+num(b.brier)+'（越低越好）；微平均 F1 '+num(m.microF1)+' ／基準 '+num(b.microF1)+'。'+(Number.isFinite(m.brier)&&Number.isFinite(b.brier)?(m.brier<b.brier?'此批留出平方誤差低於詞頻基準；尚未完成外部驗證。':'此批結果尚未優於詞頻基準，模型分數須保留探索性解讀。'):'支持不足的目標不給分數。')+(m.microF1===0?' 固定門檻未命中正例，F1 為 0；目前不足以可靠還原方義。':'')+'</div>'}
 function evidenceState(f){return ['linked_source_span','linked_literal_values'].includes(f?.evidenceStatus)?'有原文位置':f?.evidenceStatus==='field_spans_present_some_values_not_literal_linked'?'部分原詞可定位・其餘待核':f?.evidenceStatus==='unknown'||f?.status==='unknown'||!f?.values?.length&&!f?.recorded?'原詞未錄':'已錄標籤・原詞定位待補核'}
 function fieldEvidenceHTML(label,f){return '<p><strong>'+esc(label)+'</strong> · '+esc(evidenceState(f))+'<br>'+((f?.evidence||[]).map(e=>'「'+esc(e.text)+'」 ['+e.start+', '+e.end+')').join('；')||'未提供可定位原詞')+(f?.unlinkedOrNormalizedValues?.length?'<br>未直接定位／整理標籤：'+f.unlinkedOrNormalizedValues.map(esc).join('、'):'')+'</p>'}
 function rowsHTML(){const found=matches();page=Math.max(0,Math.min(page,Math.ceil(found.length/20)-1));return '<div class="table-scroll"><table class="research-table vector-table"><thead><tr><th>本草條目</th><th>寒熱來源序位</th><th>味／歸經原詞</th><th>八維功用原詞</th><th>從原方學得的向量</th></tr></thead><tbody>'+found.slice(page*20,(page+1)*20).map(h=>'<tr><td><button class="text-button" data-vector-herb="'+esc(h.id)+'">'+esc(h.name)+'</button><small>'+source(h.sourceId)+'</small></td><td>'+range(h.thermal?.range)+'<small>'+esc(h.thermal?.recorded||'性未錄')+'</small><small>'+esc(evidenceState(h.thermal))+'</small></td><td>'+esc(h.flavors?.values?.join('、')||'味未錄')+'<small>'+esc(evidenceState(h.flavors))+'</small><small>'+esc(h.meridians?.values?.join('、')||'歸經未錄')+' · '+esc(evidenceState(h.meridians))+'</small></td><td>'+(h.effects?.axes||[]).map(a=>'<span class="vector-token '+(a.present?'active':'')+'" title="'+esc(a.present?'有來源原詞命中':'詞典未命中；不是無作用')+'">'+esc(a.label)+' '+(a.present?'1':'·')+'</span>').join('')+'</td><td>'+learnedState(h)+'<small>'+(h.learned?.mappedElements||[]).map(e=>esc(e.sourceName)+'：'+(e.presentGroups??0)+' 獨立組').join('；')+'</small></td></tr>').join('')+'</tbody></table></div><div class="pager"><span>'+found.length+' 條 · 第 '+(page+1)+' / '+Math.max(1,Math.ceil(found.length/20))+' 頁</span><button class="button secondary" data-vector-page="-1" '+(!page?'disabled':'')+'>上一頁</button><button class="button secondary" data-vector-page="1" '+((page+1)*20>=found.length?'disabled':'')+'>下一頁</button></div>'}
 function herbHTML(){const h=vectors().find(h=>h.id===herbId);if(!h)return '';const learned=h.learned||V().herbProfile(getModel(),herbId).learned;return '<section class="panel research-panel" id="vector-herb-detail"><div class="panel-heading"><h2>'+esc(h.name)+' · 單味量化記錄</h2><button class="button secondary" data-detail="'+esc(h.id)+'">查看本草原文</button></div><div class="vector-detail-grid"><div><h3>來源特性向量</h3><div class="profile-summary"><div><span>寒熱區間</span><b>'+range(h.thermal?.range)+'</b></div><div><span>味標籤</span><b>'+esc(h.flavors?.values?.join('、')||'未知')+'</b></div></div><p>歸經：'+esc(h.meridians?.values?.join('、')||'未知')+'</p><div class="vector-source-axes">'+(h.effects?.axes||[]).map(a=>'<div><span>'+esc(a.label)+'</span><b>'+(a.present?'1 · 原詞命中':'未命中')+'</b></div>').join('')+'</div><p class="rule-note">寒熱是文獻序位，沒有藥效單位。功用詞的 1 表示有可定位原詞；未命中不能判定無此作用。不同炮製分支的向量在工作台另行選取。</p><details><summary>查看逐項原詞與證據</summary>'+fieldEvidenceHTML('性',h.thermal)+fieldEvidenceHTML('味',h.flavors)+fieldEvidenceHTML('歸經',h.meridians)+(h.effects?.axes||[]).filter(a=>a.present).map(a=>'<p><strong>'+esc(a.label)+'</strong><br>'+a.evidence.map(e=>'「'+esc(e.text)+'」').join('；')+'</p>').join('')+'<p>'+source(h.sourceId)+'</p></details></div><div><h3>學得的主治詞條件向量</h3><p class="rule-note">係數 β 是原名成分存在時，在其他已錄成分條件下的文獻銀詞關聯。正／負不表示補瀉、毒性或實際作用方向。</p>'+(learned.mappedElements?.length?learned.mappedElements.map(e=>'<div class="vector-element"><strong>'+esc(e.sourceName)+'</strong><p>'+e.support+' 方 · 含此元素 '+e.presentGroups+' 組／未列 '+e.absentGroups+' 組</p>'+(!e.reportable?'<div class="notice">'+esc(e.reason||'尚不能估計單味係數')+(e.identicalOccurrenceElements?.length?'<br>完全同現：'+e.identicalOccurrenceElements.map(esc).join('、'):'')+'</div>':'')+'<div class="vector-coefficients">'+(e.coefficients||[]).map(t=>'<div><span>'+esc(t.label)+'</span><b>'+num(t.coefficient)+'</b><small>'+esc(t.coefficient===null?t.reason||'支持不足':'條件係數；非單味效力')+'</small></div>').join('')+'</div></div>').join(''):'<div class="notice">此條目尚無已錄原方的唯一文字對映。來源特性向量已建立，學得係數保留未知。</div>')+'</div></div></section>'}
 function options(){return '<option value="workbench" '+(formulaId==='workbench'?'selected':'')+'>目前工作台 · 自選材料</option>'+c.formulas.map(f=>'<option value="'+esc(f.id)+'" '+(f.id===formulaId?'selected':'')+'>'+esc(f.name)+' · '+esc(f.sourceBook)+'</option>').join('')}
 function formulaSourceHTML(){if(formulaId==='workbench')return '<p>研究名稱：'+esc(ctx.name())+'</p><p class="rule-note">成分原名有／無進入學得模型；工作台克數與炮製實錄保留於記錄。所選炮製分支只影響來源特性分布，尚無參數與藥效的訓練資料。</p>';const f=F(formulaId);if(!f)return '';return '<h3>'+esc(f.name)+' · 原方材料</h3><blockquote class="source-quote">'+esc(f.rawIngredientText)+'</blockquote><p>'+link(f.sourceURL,f.sourceBook)+' · '+esc(f.sourceChapter)+'</p><p class="rule-note">原名材料全部保留，包含未對映目錄的材料。古籍數量保留原文；此模型以成分有／無輸入，不將兩、錢或枚換算為克數。</p>'}
 function sourceSummary(){if(formulaId==='workbench'){const r=ctx.processing();return {quant:ctx.selection().length?r.quant:null,empty:!ctx.selection().length,complete:!!ctx.selection().length,missing:[],coverage:ctx.selection().length?1:0,processing:{version:r.version,basis:r.basis,gramsComplete:r.gramsComplete,totalGrams:r.totalGrams,knownGrams:r.knownGrams,missingGrams:r.missingGrams,resolvedRows:r.resolvedRows,changes:r.changes,limitations:r.limitations}}}const f=F(formulaId),refs=(f?.ingredientRefs||[]).filter(r=>r.scope==='core'),ids=[...new Set(refs.filter(r=>r.id&&H(r.id)).map(r=>r.id))],q=Q.aggregate(ids.map(id=>({id,ratio:1})),d),missing=refs.filter(r=>!r.id||!H(r.id));return {quant:q,complete:!missing.length,missing,coverage:refs.length?(refs.length-missing.length)/refs.length:0,total:refs.length}}
 function sourceSummaryHTML(){const r=runArtifact?.sourceProfile||sourceSummary(),q=r.quant;if(!q)return '<div class="notice">'+(r.empty?'工作台尚無材料，無法計算全方輪廓。':'工作台克數未完整，來源特性全方輪廓保留未知。')+'</div>';const full=r.complete&&!q.unknownIds.length;return '<h3>由單味來源向量組合的輪廓</h3><div class="profile-summary"><div><span>全方寒熱序位</span><b>'+range(full?q.range:null)+'</b></div><div><span>材料目錄對映</span><b>'+pct(r.coverage)+'</b></div><div><span>已對映子集區間</span><b>'+range(q.knownSubsetRange)+'</b></div></div>'+(!r.complete?'<div class="notice">未對映材料：'+r.missing.map(x=>esc(x.sourceName)).join('、')+'。全方寒熱與來源功用覆蓋保留未知，子集不代表完整原方。</div>':'')+(q.unknownIds.length?'<p class="rule-note">性資料未知：'+q.unknownIds.map(id=>esc(H(id).name)).join('、')+'。</p>':'')+'<div class="vector-source-axes">'+q.labels.map(a=>'<div><span>'+esc(a.label)+'</span><b>'+(r.complete?pct(a.coverage):'全方未知')+'</b></div>').join('')+'</div><p class="rule-note">文獻功用原詞涵蓋可重疊，不可相加。原方以每個已對映材料等權描述；工作台則沿用所選研究份數或完整實錄克數。原方實際藥性不能由平均序位直接判定。</p>'}
 function contributionHTML(a,r){const bundle=report()?.familyValidation?.folds?.find(f=>f.fold===r.fold)?.featureBundles?.find(b=>b.id===a.bundleId),ids=a.elementIds||bundle?.elementIds||[],names=a.sourceNames||ids.map(id=>c.sourceElements.find(e=>e.id===id)?.sourceName||id);return '<p>'+names.map(esc).join('＋')+'：'+num(a.contribution)+'<br><small>'+esc((a.individualIdentifiable??ids.length===1)?'條件貢獻':'共現束；不可拆成單味效力')+'</small></p>'}
 function scoreTable(r,actual,mode){if(!r?.terms?.length)return '<p class="empty-state">'+esc(r?.reasons?.join('；')||'資料支持不足；保留未知')+'</p>';return '<div class="table-scroll"><table class="research-table"><thead><tr><th>原文主治詞主題</th><th>模型分數</th><th>訓練詞頻基準</th><th>獨立原文對照</th><th>成分貢獻</th></tr></thead><tbody>'+r.terms.map(t=>'<tr><td>'+esc(t.label)+'</td><td>'+pct(r.abstained?null:t.modelScore)+'<small>'+esc(r.abstained?'拒絕推估':t.predicted?'達固定詞命中門檻':'未達固定門檻')+'</small></td><td>'+pct(r.abstained?null:t.baselineScore)+'</td><td>'+(actual===null?'自選組合・無獨立答案':actual.includes(t.id)?'來源原詞命中':'詞典未標記')+'</td><td><details><summary>查看加總過程</summary><p>截距 '+num(t.intercept)+'；合計 log odds '+num(t.logOdds)+'</p>'+(t.contributions||[]).map(a=>contributionHTML(a,r)).join('')+'</details></td></tr>').join('')+'</tbody></table></div><p class="rule-note">'+esc(mode)+'。分數表示此批文獻銀詞模型輸出，未作人體療效概率校準；來源未標記是詞典結果，非臨床陰性。</p>'}
 function predictionHTML(){if(!prediction)return '<p class="empty-state">選擇真實原方，查看全材料輸入、每味貢獻與獨立方義對照。</p>';const f=F(formulaId),actual=f?getModel().records.find(r=>r.id===f.id)?.silver.labelIds||[]:null;const subset=prediction.trainingSubset||{};return '<div class="inference-status"><span class="review-tag">'+esc(prediction.abstained?'支持不足・保留未知':'排除查詢方組後的全方模擬')+'</span><strong>'+esc(f?.name||ctx.name())+'</strong></div><div class="profile-summary"><div><span>原名輸入可編碼</span><b>'+pct(prediction.textElementCoverage)+'</b></div><div><span>有訓練支持元素</span><b>'+pct(prediction.supportedElementCoverage)+'</b></div><div><span>已排除來源記錄</span><b>'+(subset.excludedFormulaIds?.length||0)+'</b></div></div>'+(prediction.reasons?.length?'<div class="notice">'+prediction.reasons.map(esc).join('；')+'</div>':'')+sourceSummaryHTML()+'<h3>組合向量推估與原文核對</h3>'+(prediction.unsupportedElements?.length?'<p class="rule-note">未支持材料未進入係數加總，其貢獻仍未知；以下分數來自可估的特徵子集。</p>':'')+scoreTable(prediction,actual,'每次重建訓練支持與係數，排除原方及其防洩漏代理組')+(f?'<details><summary>對照原方獨立主治原文</summary><blockquote class="source-quote">'+esc(f.rawIndications)+'</blockquote>'+link(f.sourceURL,f.sourceBook)+'</details>':'')+'<details><summary>查看訓練子集、排除記錄與完整貢獻</summary><pre class="research-json">'+esc(JSON.stringify({trainingSubset:subset,unknown:prediction.unknownElements,unsupported:prediction.unsupportedElements},null,2))+'</pre></details>'}
 function validationHTML(){const r=report(),v=r?.familyValidation,b=r?.sourceBookValidation;if(!v)return '';const p=v.predictions?.find(x=>x.id===formulaId);return '<section class="panel research-panel"><h2>既有原方的留出驗證</h2><p>每個方族整組留出；係數、支持門檻、共現束與詞頻基準都只由該折訓練方重建。以下檢驗組合能否對上未參與訓練的主治銀詞。</p>'+metricsHTML(v)+(p?'<details><summary>查看目前原方的五折留出對照</summary>'+scoreTable(p,p.actualLabelIds||[],'此筆來自 '+p.fold+' 折的留出查詢，未在該折訓練')+'</details>':'')+'<div class="vector-validation-grid">'+[v,b].filter(Boolean).map((x,i)=>'<div><h3>'+(i?'整部來源書留出':'五折方族留出')+'</h3><p>模型 Brier '+num(x.metrics?.brier)+' ／基準 '+num(x.baselineMetrics?.brier)+'</p><p>可評估查詢 '+(x.coverage?.scoredQueryRecords??x.coverage?.scoredQueries??'見報告')+' ／'+c.formulas.length+' 方</p><details><summary>分組與覆蓋詳情</summary><pre class="research-json">'+esc(JSON.stringify({coverage:x.coverage,protocol:x.protocol,folds:x.folds?.map(y=>({fold:y.fold,train:y.trainIds?.length,test:y.testIds?.length,groupOverlap:y.groupOverlap,scoredDecisions:y.scoredDecisions}))},null,2))+'</pre></details></div>').join('')+'</div><p class="rule-note">資料仍是三書的自動擷取與銀標籤，尚缺獨立人工方義、完整方族譜系及外部實驗驗證。未估計藥理協同、化學成分、毒理或劑量反應。</p></section>'}
 function render(context){ctx=context;if(formulaId==='workbench'&&prediction&&runArtifact?.signature!==workbenchSignature()){prediction=null;runArtifact=null;}const r=report(),vs=vectors(),mapped=vs.filter(x=>x.learned?.mappedElements?.length).length,supported=vs.filter(x=>x.learned?.mappedElements?.some(e=>e.reportable)).length;document.querySelector('#view-content').innerHTML='<div class="research-stats"><div><b>'+d.herbs.length+'</b><span>本草來源特性向量</span></div><div><b>'+mapped+'</b><span>有原方文字對映</span></div><div><b>'+supported+'</b><span>可估單味條件向量</span></div><div><b>'+c.formulas.length+'</b><span>真實文獻方作核對</span></div></div><div class="notice">先將每味的寒熱、味、歸經與八類功用原詞編碼，再由原方成分學習主治詞關聯向量，以加總模型回到全方。文獻序位與學得係數分別保存；未知、低支持及共現不可辨識均保留。</div>'+metricsHTML(r?.familyValidation)+'<section class="panel research-panel"><h2>340 味 · 單味藥材量化</h2><p>來源向量可逐條查看；學得向量需有足夠跨方族支持。數值描述典籍與語料，未建立單味實際效力。</p><div class="research-controls"><input class="search" id="vector-search" aria-label="搜尋藥材向量" placeholder="藥名、寒熱或功用原詞" value="'+esc(search)+'"><select id="vector-support-filter" aria-label="藥材向量訓練支持"><option value="">全部本草條目</option><option value="learned" '+(supportFilter==='learned'?'selected':'')+'>可估條件關聯</option><option value="unknown" '+(supportFilter==='unknown'?'selected':'')+'>未知／支持不足</option></select></div><div id="vector-rows">'+rowsHTML()+'</div></section><div id="vector-detail-container">'+herbHTML()+'</div><section class="panel research-panel"><span class="eyebrow">HERB VECTORS → FORMULA</span><h2>從單味向量模擬真實方子</h2><div class="research-controls"><select id="vector-formula" aria-label="選擇全方模擬來源">'+options()+'</select><button class="button primary" id="run-vector-simulation">模擬全方藥性輪廓</button><button class="button secondary" id="export-vector-simulation" '+(!prediction?'disabled':'')+'>匯出全方分析</button></div><div id="vector-formula-source">'+formulaSourceHTML()+'</div><div id="vector-prediction">'+predictionHTML()+'</div></section><div id="vector-validation">'+validationHTML()+'</div>'+downloads()}
 function run(){const b=document.querySelector('#run-vector-simulation');b.disabled=true;b.textContent='重建訓練子集…';setTimeout(()=>{try{const m=getModel(),origin=ctx.origin?.()?.id,exclude=formulaId==='workbench'?(c.formulas.some(f=>f.id===origin)?origin:undefined):formulaId;prediction=V().predict(m,formulaId==='workbench'?ctx.selection():{formulaId},{excludeFormulaId:exclude});runArtifact=JSON.parse(JSON.stringify({signature:formulaId==='workbench'?workbenchSignature():null,formula:formulaId==='workbench'?{name:ctx.name(),selection:ctx.selection(),origin:ctx.origin?.(),massContext:ctx.massContext?.()}:F(formulaId),sourceProfile:sourceSummary()}));document.querySelector('#vector-prediction').innerHTML=predictionHTML();document.querySelector('#export-vector-simulation').disabled=false;ctx.notify(prediction.abstained?'支持不足；已保留未知與來源對照':'已完成全方文獻輪廓與獨立方義核對')}catch(e){ctx.notify(e.message)}finally{b.disabled=false;b.textContent='模擬全方藥性輪廓'}},20)}
 function download(value){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}));a.href=url;a.download='單味向量與全方模擬.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 document.addEventListener('input',e=>{if(e.target.id==='vector-search'){search=e.target.value;page=0;document.querySelector('#vector-rows').innerHTML=rowsHTML()}});
 document.addEventListener('change',e=>{if(e.target.id==='vector-support-filter'){supportFilter=e.target.value;page=0;document.querySelector('#vector-rows').innerHTML=rowsHTML()}if(e.target.id==='vector-formula'){formulaId=e.target.value;prediction=null;runArtifact=null;document.querySelector('#vector-formula-source').innerHTML=formulaSourceHTML();document.querySelector('#vector-prediction').innerHTML=predictionHTML();document.querySelector('#vector-validation').innerHTML=validationHTML();document.querySelector('#export-vector-simulation').disabled=true}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.vectorHerb){herbId=b.dataset.vectorHerb;document.querySelector('#vector-detail-container').innerHTML=herbHTML();document.querySelector('#vector-herb-detail').scrollIntoView({behavior:'smooth',block:'start'})}if(b.dataset.vectorPage){page+=Number(b.dataset.vectorPage);document.querySelector('#vector-rows').innerHTML=rowsHTML()}if(b.id==='run-vector-simulation')run();if(b.id==='export-vector-simulation'&&prediction){if(formulaId==='workbench'&&runArtifact.signature!==workbenchSignature()){prediction=null;runArtifact=null;render(ctx);ctx.notify('工作台已變更，請重新模擬再匯出');return}const r=report();download({createdAt:new Date().toISOString(),purpose:'單味文獻向量與全方主治銀詞模擬；非人體藥效',modelVersion:V().version,parameters:getModel().config,formula:runArtifact.formula,sourceProfile:runArtifact.sourceProfile,prediction,validation:{family:r?.familyValidation,sourceBook:r?.sourceBookValidation},provenance:r?.provenance,limitations:prediction.limitations});ctx.notify('已匯出單味貢獻、來源輪廓與留出核對')}}
 );
 return {render};
})();
